-- =====================================================================================================
-- 00_PRECHECK_CLOUD.sql — SCP0100 Global PSI Report 클라우드 이관(DB 만) 선판정 · 조회 전용(변경 없음)
--   SOURCE-FRESH: 기대값 = 사내 ZIOUI1(localhost) 2026-10-30 16:17:24 실측. 전체 F5 1회 — 결과 그리드를 아래 기대값과 대조한다.
--   실행 계정 = SCM_MGR (권한 조회 ALL_TAB_PRIVS 는 소유자 세션에서만 전부 보인다). 치환변수·바인드 없음.
--   마지막 PL/SQL 블록만 '중단 조건'(라벨 코드 선점)에서 ORA-20001 을 낸다. 그 외 문장은 모두 SELECT.
-- =====================================================================================================

-- [P1] PKG_SCP0100 존재·상태 (기대: PACKAGE VALID · PACKAGE BODY VALID — 이 패키지는 PKG 를 바꾸지 않는다. 없으면 PKG 선이관 필요 → README §4)
SELECT 'P1' STEP, OBJECT_TYPE, STATUS, TO_CHAR(LAST_DDL_TIME,'YYYY-MM-DD HH24:MI:SS') LAST_DDL,
       (SELECT COUNT(*) FROM ALL_SOURCE S WHERE S.OWNER=O.OWNER AND S.NAME=O.OBJECT_NAME AND S.TYPE=O.OBJECT_TYPE) LINES
  FROM ALL_OBJECTS O WHERE OWNER='SCM_MGR' AND OBJECT_NAME='PKG_SCP0100' ORDER BY OBJECT_TYPE;
--   사내 실측: PACKAGE 108줄(LAST_DDL 2026-10-09 13:38:32) · PACKAGE BODY 5107줄(LAST_DDL 2026-10-16 09:42:30)
--   줄 수가 다르면 세대 차이 — 사내 BODY 이력 마커: * 2026.09.23   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환 | * 2026.10.07   AJS          [속도] 최종 피벗의 칸별 스칼라 하위질의(칸 수 x 행 수)를 수량 집계 바깥 조인 1회 + CASE 로 변경, 수량 임시 테이블 적재 생략(AUTO · CELL_ | * 2026.10.16   AJS          Project 조회조건 쉼표 구분 복수 조회(부분 일치 유지 · WW · MM DATAONLY)
--   (타 작업자 AJS 2026.10.07·10.16 변경분은 본 패키지 범위 밖 — 사용자 본인 작업만 이관 규칙. README §2 표)
SELECT 'P1b' STEP, SUBSTR(TEXT,1,120) MARKER_LINE FROM ALL_SOURCE WHERE OWNER='SCM_MGR' AND NAME='PKG_SCP0100' AND TYPE='PACKAGE BODY' AND LINE BETWEEN 1 AND 30 AND REGEXP_LIKE(TEXT,'^\s*\*\s+2026\.[0-9]{2}\.[0-9]{2}\s') ORDER BY LINE;
SELECT 'P1c' STEP, PROCEDURE_NAME FROM ALL_PROCEDURES WHERE OWNER='SCM_MGR' AND OBJECT_NAME='PKG_SCP0100' AND PROCEDURE_NAME IS NOT NULL ORDER BY SUBPROGRAM_ID;
--   사내 실측 서브프로그램 6: P_SCP0100_GET_GLOBAL_PSI_REPORT, P_SCP0100_GET_GLOBAL_PSI_REPORT_WW_DATAONLY, P_SCP0100_GET_GLOBAL_PSI_REPORT_MM_DATAONLY, P_SCP0100_GET_PLAN_DATE, P_SCP0100_GET_SHEET_CALENDAR_3SPAN, P_SCP0100_GET_SITE

-- [P2] PKG 가 참조하는 GTT (사내 26개 전부 존재해야 함 — 없으면 PKG BODY 가 INVALID 가 된다. 이 패키지는 GTT 를 만들지 않는다(화면 작업으로 생성·수정된 GTT 없음))
SELECT 'P2' STEP, COUNT(*) GTT_FOUND, 26 GTT_EXPECTED FROM ALL_TABLES WHERE OWNER='SCM_MGR' AND TEMPORARY='Y' AND TABLE_NAME IN ('GT_SCP0100_ALL', 'GT_SCP0100_ALL_DISPLAY_SEQ', 'GT_SCP0100_ALL_MEASURE_UI', 'GT_SCP0100_ALL_VARIOUS_KEY', 'GT_SCP0100_CELL_GROUP_SORT_ORDER', 'GT_SCP0100_DAYCOLS', 'GT_SCP0100_DIO_DETAIL_RAW', 'GT_SCP0100_FINAL', 'GT_SCP0100_LINE', 'GT_SCP0100_MEASURE', 'GT_SCP0100_MEASURE1', 'GT_SCP0100_MEASURE2', 'GT_SCP0100_MEASURE3', 'GT_SCP0100_OPERATION', 'GT_SCP0100_PRODUCTLEVEL', 'GT_SCP0100_QTY_AUTO', 'GT_SCP0100_QTY_CELL_GROUP', 'GT_SCP0100_QTY_CELL_GROUP_DETAIL', 'GT_SCP0100_QTY_DETAIL', 'GT_SCP0100_QTY_PRODUCT_LEVEL1', 'GT_SCP0100_QTY_PRODUCT_LEVEL2', 'GT_SCP0100_QTY_PRODUCT_LEVEL3', 'GT_SCP0100_RAW', 'GT_SCP0100_RAW_CELL_CF', 'GT_SCP0100_TRANSPORT_MODE_CODE', 'GT_SCP0100_USER_COLS');
SELECT 'P2b' STEP, COLUMN_VALUE MISSING_GTT FROM TABLE(SYS.ODCIVARCHAR2LIST('GT_SCP0100_ALL', 'GT_SCP0100_ALL_DISPLAY_SEQ', 'GT_SCP0100_ALL_MEASURE_UI', 'GT_SCP0100_ALL_VARIOUS_KEY', 'GT_SCP0100_CELL_GROUP_SORT_ORDER', 'GT_SCP0100_DAYCOLS', 'GT_SCP0100_DIO_DETAIL_RAW', 'GT_SCP0100_FINAL', 'GT_SCP0100_LINE', 'GT_SCP0100_MEASURE', 'GT_SCP0100_MEASURE1', 'GT_SCP0100_MEASURE2', 'GT_SCP0100_MEASURE3', 'GT_SCP0100_OPERATION', 'GT_SCP0100_PRODUCTLEVEL', 'GT_SCP0100_QTY_AUTO', 'GT_SCP0100_QTY_CELL_GROUP', 'GT_SCP0100_QTY_CELL_GROUP_DETAIL', 'GT_SCP0100_QTY_DETAIL', 'GT_SCP0100_QTY_PRODUCT_LEVEL1', 'GT_SCP0100_QTY_PRODUCT_LEVEL2', 'GT_SCP0100_QTY_PRODUCT_LEVEL3', 'GT_SCP0100_RAW', 'GT_SCP0100_RAW_CELL_CF', 'GT_SCP0100_TRANSPORT_MODE_CODE', 'GT_SCP0100_USER_COLS')) WHERE COLUMN_VALUE NOT IN (SELECT TABLE_NAME FROM ALL_TABLES WHERE OWNER='SCM_MGR' AND TEMPORARY='Y');

-- [P3] PKG 외부 참조 객체 (함수·뷰·테이블·시노님 — 사내 16개, 전부 기존 공용 자산 · 이 패키지 미포함 · 존재 확인만)
SELECT 'P3' STEP, D.TYPE_ EXPECTED_TYPE, D.OWNER_, D.NAME_, NVL((SELECT MAX(STATUS) FROM ALL_OBJECTS O WHERE O.OWNER=D.OWNER_ AND O.OBJECT_NAME=D.NAME_ AND O.OBJECT_TYPE=D.TYPE_),'** MISSING **') STATUS
  FROM (
       SELECT 'SCM_MGR' OWNER_, 'FN_CHAR_TO_DATE' NAME_, 'FUNCTION' TYPE_ FROM DUAL
       UNION ALL SELECT 'SCM_MGR' OWNER_, 'FN_GET_REPORT_USER_COLUMNS' NAME_, 'FUNCTION' TYPE_ FROM DUAL
       UNION ALL SELECT 'SCM_MGR' OWNER_, 'FN_SPLITSTRING' NAME_, 'FUNCTION' TYPE_ FROM DUAL
       UNION ALL SELECT 'SCM_MGR' OWNER_, 'SCM_MST_ITEM_SN' NAME_, 'SYNONYM' TYPE_ FROM DUAL
       UNION ALL SELECT 'SCM_MGR' OWNER_, 'SCM_ADM_LOOKUP_MASTER_DETAIL' NAME_, 'TABLE' TYPE_ FROM DUAL
       UNION ALL SELECT 'SCM_MGR' OWNER_, 'SCM_MST_SHEET_COLUMNS' NAME_, 'TABLE' TYPE_ FROM DUAL
       UNION ALL SELECT 'SCM_MGR' OWNER_, 'SCM_MST_SHEET_MEASURE' NAME_, 'TABLE' TYPE_ FROM DUAL
       UNION ALL SELECT 'SCM_MGR' OWNER_, 'SCM_MST_TITLESET_USER' NAME_, 'TABLE' TYPE_ FROM DUAL
       UNION ALL SELECT 'SCM_MGR' OWNER_, 'SCM_SYS_CALENDAR_M' NAME_, 'TABLE' TYPE_ FROM DUAL
       UNION ALL SELECT 'SCM_MGR' OWNER_, 'SCP_MST_FINAL_ITEM' NAME_, 'TABLE' TYPE_ FROM DUAL
       UNION ALL SELECT 'SCM_MGR' OWNER_, 'SCP_PLN_INTERFACE_YN' NAME_, 'TABLE' TYPE_ FROM DUAL
       UNION ALL SELECT 'SCM_MGR' OWNER_, 'SCP_RPT_GLOBAL_PSI_MD_DETAIL_MM' NAME_, 'TABLE' TYPE_ FROM DUAL
       UNION ALL SELECT 'SCM_MGR' OWNER_, 'SCP_RPT_GLOBAL_PSI_MD_DETAIL_WW' NAME_, 'TABLE' TYPE_ FROM DUAL
       UNION ALL SELECT 'SCM_MGR' OWNER_, 'SCP_RPT_GLOBAL_PSI_MD_MM' NAME_, 'TABLE' TYPE_ FROM DUAL
       UNION ALL SELECT 'SCM_MGR' OWNER_, 'SCP_RPT_GLOBAL_PSI_MD_WW' NAME_, 'TABLE' TYPE_ FROM DUAL
       UNION ALL SELECT 'SCM_MGR' OWNER_, 'SCP_PLAN_VERSION_V' NAME_, 'VIEW' TYPE_ FROM DUAL
       ) D ORDER BY 2,4;

-- [P4] 앱 계정 SCMP_APP — PKG_SCP0100 EXECUTE 권한 + 시노님 (사내 실측: SCMP_APP:EXECUTE / 시노님 SCMP_APP.PKG_SCP0100->SCM_MGR.PKG_SCP0100). 이 패키지는 GRANT 를 실행하지 않는다(사내 이번 작업 중 실행한 GRANT 없음).
SELECT 'P4' STEP, GRANTEE, PRIVILEGE FROM ALL_TAB_PRIVS WHERE TABLE_SCHEMA='SCM_MGR' AND TABLE_NAME='PKG_SCP0100' ORDER BY 1,2;
SELECT 'P4b' STEP, OWNER, SYNONYM_NAME, TABLE_OWNER, TABLE_NAME FROM ALL_SYNONYMS WHERE TABLE_NAME='PKG_SCP0100' ORDER BY 1;
--   0행이면 클라우드 DBA 에게 GRANT EXECUTE ON SCM_MGR.PKG_SCP0100 TO SCMP_APP + CREATE OR REPLACE SYNONYM SCMP_APP.PKG_SCP0100 FOR SCM_MGR.PKG_SCP0100 요청(본 패키지 범위 밖 · README §4)

-- [P5] META 7영역 + MENU 행수 (사내 실측값과 같아야 한다. 이 패키지는 SHEET_COLUMNS PLAN_TYPE 3행만 추가한다)
SELECT 'P5' STEP, K, CNT, EXPECTED, CASE WHEN CNT=EXPECTED THEN 'OK' ELSE 'DIFF' END JUDGE FROM (
       SELECT 'SCM_ADM_MNU_M' K, (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_MNU_M WHERE MNU_ID='SCP0100') CNT, 1 EXPECTED FROM DUAL
       UNION ALL SELECT 'SCM_ADM_API_M(BTN 배선 API)' K, (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_API_M WHERE API_ID IN (SELECT API_ID FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID='SCP0100')) CNT, 4 EXPECTED FROM DUAL
       UNION ALL SELECT 'SCM_ADM_MNU_BTN_MPG_M' K, (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID='SCP0100') CNT, 9 EXPECTED FROM DUAL
       UNION ALL SELECT 'SCM_ADM_PROC_M(PKG_SCP0100.%)' K, (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM LIKE 'PKG_SCP0100.%') CNT, 33 EXPECTED FROM DUAL
       UNION ALL SELECT 'SCM_ADM_USER_GR_MNU_MPG_M' K, (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_USER_GR_MNU_MPG_M WHERE MNU_ID='SCP0100') CNT, 5 EXPECTED FROM DUAL
       UNION ALL SELECT 'SCM_ADM_USER_GR_MNU_BTN_MPG_M' K, (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_USER_GR_MNU_BTN_MPG_M WHERE MNU_ID='SCP0100') CNT, 45 EXPECTED FROM DUAL
       UNION ALL SELECT 'SCM_MST_SHEET_COLUMNS(PLAN_TYPE 제외 기존)' K, (SELECT COUNT(*) FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='SCP0100' AND COLUMN_NAME<>'PLAN_TYPE') CNT, 33 EXPECTED FROM DUAL
       UNION ALL SELECT 'SCM_MST_SHEET_COLUMNS(PLAN_TYPE — 적용 전 0 가능)' K, (SELECT COUNT(*) FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='SCP0100' AND COLUMN_NAME='PLAN_TYPE') CNT, 3 EXPECTED FROM DUAL
       UNION ALL SELECT 'SCM_MST_SHEET_MEASURE' K, (SELECT COUNT(*) FROM SCM_MGR.SCM_MST_SHEET_MEASURE WHERE PROGRAM_ID='SCP0100') CNT, 36 EXPECTED FROM DUAL
       UNION ALL SELECT 'SCM_ADM_MSG_M(MNU_SCP0100)' K, (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_MSG_M WHERE MSG_ID='MNU_SCP0100') CNT, 3 EXPECTED FROM DUAL
       UNION ALL SELECT 'SCM_ADM_LOOKUP_MASTER_DETAIL(SHEET_PRSL_YN)' K, (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE='SHEET_PRSL_YN' AND SEGMENT1='SCP0100') CNT, 4 EXPECTED FROM DUAL
       UNION ALL SELECT 'SCM_ADM_CMBO_SQL_M(화면 콤보 4)' K, (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_CMBO_SQL_M WHERE SQL_ID IN ('Division_SCP','PlanType1_SCP_ALL','PLAN_END_DATE_REPORT','SCPPlanPeriod_SCP')) CNT, 4 EXPECTED FROM DUAL
       UNION ALL SELECT 'SCM_ADM_LOOKUP_MASTER_DETAIL(화면 lookup 5 TYPE)' K, (SELECT COUNT(DISTINCT LOOKUP_TYPE) FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE IN ('STOCK_TREND_DISPLAY','PRODUCT_LEVEL','BUCKET_TYPE_CODE','SCP_UNIT_QTY','PLAN_TYPE')) CNT, 5 EXPECTED FROM DUAL
       ) ORDER BY K;
--   SCM_MST_SHEET_COLUMNS(PLAN_TYPE) 가 0 이면 30 파일이 3행 INSERT · 3 이면 값 비교 후 다른 행만 UPDATE(같으면 0행) · 1~2 면 부족분만 INSERT
--   그 밖의 K 가 DIFF 이면 SCP0100 기본 등록(ZIONEX 2026-09-23 변환 산출물) 세대가 다른 것 — 본 패키지 범위 밖, README §4 로 보고

-- [P6] 메뉴 행 상세 (사내: UPPR_MNU_ID=Supply_Plan · MNU_URL=global-psi-report · ROUTE_PATH=supply/global-psi-report · MNU_MSG_ID=MNU_SCP0100 · USE_YN=Y)
SELECT 'P6' STEP, MNU_ID, UPPR_MNU_ID, MNU_URL, ROUTE_PATH, MNU_MSG_ID, MNU_TP_CD, UNIT_TP_CD, SORT_ORD, MNU_LV_NO, USE_YN FROM SCM_MGR.SCM_ADM_MNU_M WHERE MNU_ID IN ('SCP0100','Supply_Plan') ORDER BY MNU_LV_NO;

-- [P7] 배선 역추적 (화면이 부르는 SP 가 전부 있고 PROC_M 행수 = ALL_ARGUMENTS 인자수인지 — 정상 = 전 행 PROC_M_ROWS = ARG_CNT, ARG_CNT 0 = SP 부재)
SELECT 'P7' STEP, B.SHT_NM, B.MNU_BTN_CD, A.API_URL,
       (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_PROC_M P WHERE P.PROC_NM=A.API_URL) PROC_M_ROWS,
       (SELECT COUNT(*) FROM ALL_ARGUMENTS G WHERE G.OWNER='SCM_MGR' AND G.PACKAGE_NAME=SUBSTR(A.API_URL,1,INSTR(A.API_URL,'.')-1) AND G.OBJECT_NAME=SUBSTR(A.API_URL,INSTR(A.API_URL,'.')+1) AND G.DATA_LEVEL=0 AND G.ARGUMENT_NAME IS NOT NULL) ARG_CNT
  FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M B JOIN SCM_MGR.SCM_ADM_API_M A ON A.API_ID=B.API_ID
 WHERE B.MNU_ID='SCP0100' ORDER BY 2,3;
--   사내 실측: P_SCP0100_GET_GLOBAL_PSI_REPORT PROC_M 19 / ARG 19 · P_SCP0100_GET_PLAN_DATE PROC_M 5 / ARG 5 · P_SCP0100_GET_SHEET_CALENDAR_3SPAN PROC_M 4 / ARG 4 · P_SCP0100_GET_SITE PROC_M 5 / ARG 5

-- [P8] 화면 FE 가 쓰는 라벨·메시지 코드 25개 존재 (기존 재사용 23 = 존재 확인만 · 신규 2 = LBL01163·LBL01167 → 31 파일) — 적용 전엔 신규 2개만 MISSING 허용
SELECT 'P8' STEP, COLUMN_VALUE MISSING_CODE FROM TABLE(SYS.ODCIVARCHAR2LIST('MSG00097', 'LBL01167', 'LBL01163', 'LBL00112', 'MSG00704', 'MSG00703', 'MSG00618', 'LBL01129', 'LBL01073', 'LBL00767', 'LBL00710', 'LBL00690', 'LBL00684', 'LBL00683', 'LBL00605', 'LBL00310', 'LBL00050', 'LBL00049', 'LBL00040', 'LBL00039', 'LBL00023', 'LBL00022', 'LBL00021', 'LBL00012', 'LBL00001')) WHERE COLUMN_VALUE NOT IN (SELECT MSG_ID FROM SCM_MGR.SCM_ADM_MSG_M);
SELECT 'P8b' STEP, MSG_ID, LANG_CD, MSG_NM, MSG_TP_CD, USE_YN, CREATED_BY FROM SCM_MGR.SCM_ADM_MSG_M WHERE MSG_ID IN ('LBL01163', 'LBL01167') ORDER BY 1,2;
--   사내 실측: LBL01163=Scale(minyonglee1,2026-10-15 17:11:29) · LBL01167=A/S(minyonglee1,2026-10-19 09:52:20)

-- [P9] 적용 전 PLAN_TYPE 행 현재값 (클라우드에 이미 있으면 여기 결과를 보관 — 99_ROLLBACK 은 이 패키지가 INSERT 한 행만 지운다)
SELECT 'P9' STEP, SHEET_NAME, COLUMN_LABEL_NAME, SORT_ORDER_NO, SMALL_CLASS_LABEL_NAME, LARGE_CLASS_LABEL_NAME, FIXED_FLAG, COLUMN_WIDTH, CELL_CONTROL_OBJECT_TYPE_CODE, HORIZONTAL_ALIGN_CODE, UPPERCASE_APPLY_FLAG, VISIBLE_FLAG, DIVISION_ID, DEFAULT_FLAG, USER_SELECTABLE_FLAG, VALID_YN, INPUT_TP_CD, CREATED_BY, LAST_UPDATED_BY
  FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='SCP0100' AND COLUMN_NAME='PLAN_TYPE' ORDER BY SHEET_NAME;

-- [P10] 중단 조건 — 신규 라벨 코드가 클라우드에서 다른 문구로 선점돼 있으면 ORA-20001 (재채번 필요 · 31 파일 적용 금지)
DECLARE
  v_cnt NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_cnt FROM SCM_MGR.SCM_ADM_MSG_M
   WHERE ((MSG_ID = 'LBL01163' AND MSG_NM <> 'Scale') OR (MSG_ID = 'LBL01167' AND MSG_NM <> 'A/S'));
  IF v_cnt > 0 THEN
    RAISE_APPLICATION_ERROR(-20001, 'PRECHECK P10: LBL01163/LBL01167 이 클라우드에서 다른 문구로 선점됨(' || v_cnt || '행) — 재채번 후 31 파일 재생성. 적용 중단');
  END IF;
END;
/

-- 끝. 변경한 것 없음(SELECT + 판정 블록만).
